// Head values that are the same on every page. They used to be typed out here as a second copy of
// what the Lambda@Edge injector writes, which is how the two sides drifted apart. They are now
// re-exported from src/utils/staticSeo.generated.js, generated by WiSaw.cdk/scripts/publish-static-seo.js
// from the same route table the edge serves - so there is one line per value in either repository,
// and WiSaw.cdk/tests/static-route-copy-once.js fails if the committed copy goes stale.
//
// This module stays as the app's import surface so pages never import a generated file directly.

export { LOCALE, ROBOTS_INDEX, ROBOTS_NOINDEX, SITE_NAME, TWITTER_CARD } from './staticSeo.generated'
